// Parse Athena Page
//
// Input : one item = one raw Athena GetQueryResults response (one page, up to 1000 rows).
// Output: one item = { page, nextToken, rowCount, rows }, rows in Athena's own order.
//
// Runs once per page. Collect Export Rows reads every run of this node back by run index,
// so each run only has to describe its own page.

// 100 pages x 1000 rows. The export is expected to return 100-150 rows a day; a result this
// large means the date filter has gone missing.
const MAX_PAGES = 100;

// Athena column names, as aliased in the SQL. They become the spreadsheet headers.
const COLUMNS = [
  'ID',
  'Manual',
  'Player ID',
  'Brand',
  'Risk casino segment',
  'Created',
  'Updated',
  'Creating Reason',
  'Transaction type',
  'Transaction status',
  'Paid amount',
  'Currency',
  'Modified by',
  'Decline reason',
  'Notes',
  'Payment method'
];

/** Athena returns every value as a string, or omits VarCharValue entirely for NULL. */
function cellValue(cell) {
  if (cell === null || cell === undefined) return null;
  const raw = cell.VarCharValue;
  if (raw === null || raw === undefined) return null;
  return String(raw);
}

const page = $runIndex;

if (page >= MAX_PAGES) {
  throw new Error(
    `Athena result exceeds ${MAX_PAGES} pages (${MAX_PAGES * 1000} rows). The export query ` +
      'has probably lost its date filter. Investigate before raising MAX_PAGES.',
  );
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(
    `Parse Athena Page expected exactly 1 input item from Athena, received ${inputItems.length}.`,
  );
}

const response = inputItems[0].json ?? {};
const resultSet = response.ResultSet;
if (!resultSet || !Array.isArray(resultSet.Rows)) {
  throw new Error(
    'Unexpected Athena response: ResultSet.Rows is missing. Check the Get Athena Results Page node output.',
  );
}

const columns = (resultSet.ResultSetMetadata?.ColumnInfo ?? []).map((column) => column?.Name);
const missingColumns = COLUMNS.filter((column) => !columns.includes(column));
if (missingColumns.length > 0) {
  throw new Error(
    `Athena result is missing column(s): ${missingColumns.join(', ')}. The export SQL and this ` +
      'node have drifted apart. Update both together.',
  );
}

// Athena prepends a header row, on the first page only.
let rows = resultSet.Rows;
if (page === 0) {
  const firstRowValues = (rows[0]?.Data ?? []).map(cellValue);
  const firstRowIsHeader =
    firstRowValues.length === columns.length &&
    firstRowValues.every((value, index) => value === columns[index]);
  if (firstRowIsHeader) rows = rows.slice(1);
}

const records = [];
for (const row of rows) {
  const cells = row?.Data ?? [];
  const record = {};
  columns.forEach((columnName, index) => {
    record[columnName] = cellValue(cells[index]);
  });
  if (Object.values(record).every((value) => value === null)) continue;
  records.push(record);
}

return [
  {
    json: {
      page,
      nextToken: response.NextToken ?? null,
      rowCount: records.length,
      rows: records,
    },
  },
];

// Collect Export Rows
//
// Input : one item = the last page from Parse Athena Page ({ page, nextToken: null, ... }).
// Output: one item = { reportDate, fileName, rowCount, summaryText, records }.
//
// Gathers every run of Parse Athena Page in page order and writes the text of the Slack
// message. The same item feeds both branches of Rows Found?: the file upload and the
// "nothing today" notice, so the message text is defined here and nowhere else.

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Collect Export Rows expected exactly 1 input item, received ${inputItems.length}.`);
}

const lastPage = inputItems[0].json.page;
if (!Number.isInteger(lastPage) || lastPage < 0) {
  throw new Error(`Collect Export Rows received an invalid page index: ${lastPage}.`);
}

const records = [];
for (let run = 0; run <= lastPage; run++) {
  const pageItems = $('Parse Athena Page').all(0, run);
  if (pageItems.length !== 1) {
    throw new Error(
      `Parse Athena Page run ${run} produced ${pageItems.length} items, expected 1. ` +
        'Pages cannot be stitched together reliably. Nothing was sent to Slack.',
    );
  }
  records.push(...(pageItems[0].json.rows ?? []));
}

// The SQL reads "yesterday" as date_add('day', -1, current_date) in Athena, which runs on UTC.
// Mirror that here so the file name and the message name the same day as the data.
const reportDate = $now.toUTC().minus({ days: 1 }).toFormat('yyyy-MM-dd');
const fileName = `manual_deposits_${reportDate}.xlsx`;

/** Counts records by one column, e.g. { Compensation: 117, 'Courier deposit': 6 }. */
function countBy(column) {
  const counts = new Map();
  for (const record of records) {
    const key = record[column] === null || record[column] === '' ? '(empty)' : String(record[column]);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([key, count]) => `${key}: ${count}`)
    .join(', ');
}

const lines = [`Ручные депозиты ManualDeposit за ${reportDate} (UTC): ${records.length} шт.`];
if (records.length > 0) {
  lines.push(`По причине: ${countBy('Creating Reason')}`);
  lines.push(`По статусу: ${countBy('Transaction status')}`);
} else {
  lines.push('Файл не прикреплён: за сутки нет ни одной строки.');
}

return [
  {
    json: {
      reportDate,
      fileName,
      rowCount: records.length,
      summaryText: lines.join('\n'),
      records,
    },
  },
];

// Build Export Rows
//
// Input : one item = { records } from Collect Export Rows (only when rowCount > 0).
// Output: one item per record, flat, in query order. Convert to XLSX turns the set into one
//         spreadsheet: keys become the header row, in the order defined by COLUMNS.
//
// Athena hands every value over as a string. "Paid amount" is sent as a number so the sheet
// can sum and sort it; everything else stays text, so IDs keep their exact digits.

const COLUMNS = [
  'ID',
  'Manual',
  'Player ID',
  'Brand',
  'Risk casino segment',
  'Created',
  'Updated',
  'Creating Reason',
  'Transaction type',
  'Transaction status',
  'Paid amount',
  'Currency',
  'Modified by',
  'Decline reason',
  'Notes',
  'Payment method'
];
const NUMBER_COLUMNS = new Set(['Paid amount']);

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Build Export Rows expected exactly 1 input item, received ${inputItems.length}.`);
}

const records = inputItems[0].json.records;
if (!Array.isArray(records) || records.length === 0) {
  throw new Error('Build Export Rows received no records. Rows Found? should have routed this run to Post Empty Notice.');
}

function toCell(column, value) {
  if (value === null || value === undefined) return '';
  if (NUMBER_COLUMNS.has(column)) {
    const number = Number(value);
    if (!Number.isFinite(number)) {
      throw new Error(`Column "${column}" holds a non-numeric value "${value}". Check the export SQL.`);
    }
    return number;
  }
  return String(value);
}

return records.map((record) => {
  const row = {};
  for (const column of COLUMNS) row[column] = toCell(column, record[column]);
  return { json: row };
});

// Prepare Slack Upload
//
// Input : one item with the spreadsheet in binary property "data" (from Convert to XLSX).
// Output: the same item, with the fields files.getUploadURLExternal needs in json:
//         { fileName, length, title, initialComment, channelId }.
//
// Slack requires the exact byte length of the file up front, so the buffer is read here
// instead of trusting the human-readable fileSize ("12.3 kB") on the binary metadata.

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Prepare Slack Upload expected exactly 1 input item, received ${inputItems.length}.`);
}

const item = inputItems[0];
if (!item.binary || !item.binary.data) {
  throw new Error('Prepare Slack Upload received no binary "data" property. Check the Convert to XLSX node.');
}

const config = $('Config').first().json;
const channelId = String(config.slackChannelId ?? '').trim();
if (channelId === '' || channelId.startsWith('REPLACE')) {
  throw new Error('Config.slackChannelId is not set. Enter the Slack channel ID (C...) on the instance.');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buffer || buffer.length === 0) {
  throw new Error('The generated spreadsheet is empty (0 bytes). Nothing was sent to Slack.');
}

const meta = $('Collect Export Rows').first().json;

return [
  {
    json: {
      fileName: meta.fileName,
      length: buffer.length,
      title: meta.fileName,
      initialComment: meta.summaryText,
      channelId,
    },
    binary: item.binary,
  },
];

// Check Upload URL
//
// Input : one item = the files.getUploadURLExternal response. Slack answers HTTP 200 even
//         when the call fails, with { ok: false, error: '...' }, so the HTTP node never
//         fails on its own.
// Output: the Prepare Slack Upload item (json + the spreadsheet binary) extended with
//         upload_url and file_id for the next two nodes.

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Check Upload URL expected exactly 1 input item, received ${inputItems.length}.`);
}

const response = inputItems[0].json ?? {};
if (response.ok !== true) {
  throw new Error(
    `Slack files.getUploadURLExternal failed: ${response.error ?? 'no error code returned'}. ` +
      'Check the Slack API credential (bot token with files:write) on Get Slack Upload URL.',
  );
}
if (!response.upload_url || !response.file_id) {
  throw new Error('Slack files.getUploadURLExternal returned ok but no upload_url / file_id.');
}

const prepared = $('Prepare Slack Upload').first();

return [
  {
    json: { ...prepared.json, upload_url: response.upload_url, file_id: response.file_id },
    binary: prepared.binary,
  },
];

// Verify Slack Response
//
// Input : one item = a Slack Web API response, from files.completeUploadExternal or
//         chat.postMessage. Both answer HTTP 200 with { ok: false, error } on failure, so the
//         execution would otherwise look green while nothing reached the channel.
// Output: one item = { ok: true, fileIds, messageTs } for the execution log.

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Verify Slack Response expected exactly 1 input item, received ${inputItems.length}.`);
}

const response = inputItems[0].json ?? {};
if (response.ok !== true) {
  const hints = {
    not_in_channel: 'invite the bot to the channel (/invite @<app name>)',
    channel_not_found: 'check Config.slackChannelId (use the channel ID, not its name)',
    missing_scope: `add the missing scope to the Slack app: ${response.needed ?? 'see the Slack app settings'}`,
    invalid_auth: 'the bot token on the Slack API credential is wrong or revoked',
  };
  const error = response.error ?? 'no error code returned';
  throw new Error(`Slack API call failed: ${error}. ${hints[error] ?? 'See https://docs.slack.dev/reference/methods'}`);
}

return [
  {
    json: {
      ok: true,
      fileIds: Array.isArray(response.files) ? response.files.map((file) => file.id) : [],
      messageTs: response.ts ?? null,
    },
  },
];
